    51	// ---- Validation schemas (Zod) ----
    52	
    53	export const createLeaveRequestSchema = z.object({
    54	  employeeId: z.string().min(1),
    55	  leaveType: z.enum([
    56	    LeaveType.annual,
    57	    LeaveType.sick,
    58	    LeaveType.emergency,
    59	  ]),
    60	  startDate: z.coerce.date(),
    61	  endDate: z.coerce.date(),
    62	  reason: z.string().optional(),
    63	}).refine(
    64	  (data) => data.startDate <= data.endDate,
    65	  { message: 'startDate must be on or before endDate' },
    66	);
    67	
    68	export const updateLeaveRequestSchema = z.object({
    69	  leaveType: z.enum([
    70	    LeaveType.annual,
    71	    LeaveType.sick,
    72	    LeaveType.emergency,
    73	  ]).optional(),
    74	  startDate: z.coerce.date().optional(),
    75	  endDate: z.coerce.date().optional(),
    76	  reason: z.string().optional(),
    77	  status: z.enum([
    78	    LeaveStatus.draft,
    79	    LeaveStatus.submitted,
    80	    LeaveStatus.approved,
    81	    LeaveStatus.rejected,
    82	    LeaveStatus.cancelled,
    83	  ]).optional(),
    84	  approvedBy: z.string().nullable().optional(),
    85	  approvedAt: z.coerce.date().nullable().optional(),
    86	  rejectionReason: z.string().optional(),
    87	}).refine(
    88	  (data) => {
    89	    if (data.startDate !== undefined && data.endDate !== undefined) {
    90	      return data.startDate <= data.endDate;
    91	    }
    92	    return true;
    93	  },
    94	  { message: 'startDate must be on or before endDate' },
